content.content:
1	/* ============================ Đi dạo: điều phối chế độ (một mình hoặc nhiều người, máy tính) ============================
2	   Nối bản đồ va chạm (map / mapData / sceneData), chuyển động (motion), nhân vật (avatars), camera sau lưng (camera) với vòng animate, phím, chuột.
3	   `?explore=stroll` vào thẳng, đi một mình (explore/index.ts gọi start). Esc và nút Thoát dùng explore.exit() (tải lại trang, D-020).
4	   - Bản đồ dựng lần đầu vào chế độ: dữ liệu tĩnh + nhà / chân đế thu từ cảnh đã dựng (chỉ đọc, sau mọi rand()).
5	   - Nhịp quay Cầu sông Hàn đóng với người đi dạo khi cầu rời trạng thái CLOSED (spec §3 mục 13); không tự quay, không tăng tốc quay.
6	   - Ban đêm Cầu Rồng tự phun như khi bay dù (exNightStep, không đụng cầu quay).
7	   - Nhảy theo cạnh: một lần bấm Space một lần nhảy, giữ Space không nhảy liên tục (stStep nhảy mỗi khung jump = true khi chạm đất).
8	   - Phím chỉ ghi khi đang đi dạo, bỏ qua ô nhập và tổ hợp Ctrl / Meta / Alt; blur, ẩn tab, focus vào ô nhập thì xóa hết phím (Review Focus 3).
9	   - Nhiều người (exMulti, phiên kind 'walk'): xuất phát theo slot đi dạo, gửi vị trí + dáng; hết chỗ thì chế độ xem (startWatching) đặt camera sau lưng người được xem.
10	     Đổi phiên như dù lượn: bị thu chỗ → xem; mất kết nối khi đang đi → đi tiếp một mình + thông báo; mất kết nối khi xem → thoát, màn chọn báo mất kết nối.
11	   - Rời máy: phím điều khiển và kéo chuột gọi exMulti.activity().
12	   Mỗi khung không cấp phát (D-018). */
13	import { scene, camera, controls, canvas } from '../../core/renderer';
14	import { cam, keys } from '../../views/state';
15	import { CONFIG } from '../../config';
16	import { stSetGate, type StMap } from './map';
17	import { ST_GATE_SWING, stBuildStaticMap } from './mapData';
18	import { stCreate, stStep, type StState, type StInput } from './motion';
19	import { stAvatars } from './avatars';
20	import { stCollectRuntime } from './sceneData';
21	import { stCamPlace, stCamDrag, type StCam } from './camera';
22	import { stInputFromKeys } from './keys';
23	import { exNightStep } from '../nightShows';
24	import { exMulti } from '../multi';
25	import { exWatchShow, exWatchHide, exWatchRender, exFlyNotice } from '../multi/watch';
26	import type { SwingController } from '../../bridges/song-han/SwingController';
27	
28	const ST_SOLO_SLOT = -1;     // stCreate / stSpawn: đi một mình đứng giữa các điểm xuất phát
29	const ST_SOLO_AVATAR = 0;    // instance nhân vật khi đi một mình (avatars.ts)
30	
31	let map: StMap | null = null;
32	let state: StState | null = null;
33	let ctrl: SwingController | null = null;
34	let exit: () => void = () => {};   // thoát chung (explore.exit), do setupStroll nhận
35	let jumpQueued = false;      // Space vừa được bấm (không phải tự lặp): khung sau nhảy một lần
36	let selfSlot = ST_SOLO_AVATAR;   // instance nhân vật của mình: slot đi dạo khi có chỗ, giữ nguyên khi mất kết nối (màu áo không đổi)
37	let watching = false;        // đang xem người khác đi dạo (hết chỗ hoặc vừa nhường chỗ): không có nhân vật của mình, không đọc phím
38	let chased = false;          // camera đã bám người được xem lần nào chưa (lần đầu đặt thẳng, không trượt từ xa)
39	const camS: StCam = { yaw: 0, pitch: CONFIG.stroll.cam.pitch };
40	const _inp: StInput = { mx: 0, mz: 0, run: false, jump: false, camYaw: 0 };   // đầu vào tái dùng mỗi khung
41	
42	const active = () => cam.mode === 'stroll' && state !== null;
43	const inMode = () => active() || watching;   // Esc và giao diện đi dạo áp cho cả chế độ xem
44	const isField = (t: EventTarget | null) => !!t && /^(SELECT|INPUT|TEXTAREA)$/.test((t as HTMLElement).tagName || '');
45	
46	/* Một bước: cổng nhịp quay, chuyển động, nhân vật, camera, hiệu ứng đêm, người chơi khác */
47	function advance(dt: number, inp: StInput): void {
48	  if (ctrl) stSetGate(map!, ST_GATE_SWING, ctrl.state !== 'CLOSED');
49	  stStep(state!, inp, map!, dt);
50	  stAvatars.setSelf(selfSlot, state);
51	  stCamPlace(camera, controls.target, state!, camS, map!, dt);
52	  exNightStep(dt, false);
53	  const now = performance.now();
54	  exMulti.update(dt, now, null);   // người khác (đi dạo + bay), nhãn tên; không làm gì khi đi một mình
55	  exMulti.updateWalk(now, state);  // gửi vị trí + dáng khi đang giữ chỗ
56	}
57	
58	/* Mỗi khung khi xem: người khác, nhãn, danh sách; camera sau lưng người được xem (hướng camera = hướng mặt họ). Không có ai thì camera giữ nguyên */
59	function watchStep(dt: number): void {
60	  if (ctrl) stSetGate(map!, ST_GATE_SWING, ctrl.state !== 'CLOSED');
61	  exMulti.update(dt, performance.now(), null);
62	  const w = exMulti.watchWalker();
63	  if (w) { camS.yaw = w.yaw; stCamPlace(camera, controls.target, w, camS, map!, dt, !chased); chased = true; }
64	  exNightStep(dt, false);
65	}
66	
67	/* Đổi phiên khi đang xem hoặc đang đi: vào đi, mất kết nối, bị thu hồi chỗ (như onMultiChange của dù lượn) */
68	function stOnMultiChange(): void {
69	  const s = exMulti.session; if (!s) return;
70	  if (watching) {
71	    if (s.phase === 'flying') { stroll.start(); return; }   // chấp nhận lời mời: xuất phát như vào đi thường
72	    if (s.phase === 'solo') { try { sessionStorage.setItem('exMpNotice', 'lost'); } catch { /* bộ nhớ bị chặn */ } exit(); return; }   // màn chọn đọc cờ này và hiện exMpLost
73	    exWatchRender();
74	  } else if (active()) {
75	    if (s.phase === 'watching') { state = null; stAvatars.setSelf(selfSlot, null); stroll.startWatching(true); return; }   // chỗ bị thu hồi (rời máy): sang xem, camera giữ nguyên
76	    if (s.phase === 'solo' && s.notice === 'lost') exFlyNotice(s, 'stLost');   // vẫn đi, người khác đã biến mất
77	  }
78	}
79	
80	/* Bản đồ dựng lần đầu vào chế độ (đi hoặc xem); cổng nhịp quay theo cầu hiện tại */
81	function stEnsureMap(): StMap {
82	  if (!map) { map = stBuildStaticMap(); stCollectRuntime(map); }
83	  if (ctrl) stSetGate(map, ST_GATE_SWING, ctrl.state !== 'CLOSED');
84	  return map;
85	}
86	
87	export const stroll = {
88	  active,
89	  inMode,
90	  get watching(): boolean { return watching; },
91	  get state(): StState | null { return state; },
92	  get map(): StMap | null { return map; },
93	  get cam(): StCam { return camS; },
94	  /* Vào đi: một mình (không phiên / ngoại tuyến) hoặc với slot đi dạo vừa được cấp (xuất phát lệch theo slot) */
95	  start(): void {
96	    if (watching) { watching = false; document.body.classList.remove('ex-watching'); exWatchHide(); }
97	    const m = stEnsureMap(), s = exMulti.session;
98	    const slot = s && s.kind === 'walk' && s.mySlot >= 0 ? s.mySlot : ST_SOLO_SLOT;
99	    if (s) exMulti.onChange = stOnMultiChange;
100	    selfSlot = slot >= 0 ? slot : ST_SOLO_AVATAR;
101	    state = stCreate(m, slot);
102	    camS.yaw = state.yaw; camS.pitch = CONFIG.stroll.cam.pitch;
103	    const mesh = stAvatars.build();
104	    if (!mesh.parent) scene.add(mesh);
105	    stAvatars.setSelf(selfSlot, state);
106	    keys.clear(); jumpQueued = false;
107	    cam.flight.then = null; cam.mode = 'stroll'; controls.enabled = false;
108	    stCamPlace(camera, controls.target, state, camS, m, 0, true);
109	    document.body.classList.add('explore', 'stroll');
110	  },
111	  /* Chế độ xem: cam.mode = 'stroll' nhưng không có nhân vật của mình; carry = true khi vừa nhường chỗ (camera đang ở sau lưng mình, trượt dần sang người được xem) */
112	  startWatching(carry = false): void {
113	    const s = exMulti.session; if (!s) return;
114	    stEnsureMap();
115	    const mesh = stAvatars.build();
116	    if (!mesh.parent) scene.add(mesh);
117	    watching = true; chased = carry; state = null;
118	    keys.clear(); jumpQueued = false;
119	    camS.pitch = CONFIG.stroll.cam.pitch;
120	    cam.flight.then = null; cam.mode = 'stroll'; controls.enabled = false;
121	    document.body.classList.add('explore', 'stroll', 'ex-watching');
122	    exMulti.onChange = stOnMultiChange;
123	    exWatchShow(s);
124	  },
125	  update(dt: number): void {
126	    if (watching) { watchStep(dt); return; }
127	    if (!active()) return;
128	    stInputFromKeys(keys, camS.yaw, _inp);
129	    _inp.jump = jumpQueued; jumpQueued = false;
130	    advance(dt, _inp);
131	  },
132	  /* Cho test: như update nhưng nhận đầu vào trực tiếp */
133	  step(dt: number, inp: StInput): void {
134	    if (active()) advance(dt, inp);
135	  }
136	};
137	
138	/* onExit: thoát chung (explore.exit), dùng khi mất kết nối lúc đang xem */
139	export function setupStroll(c: SwingController, onExit: () => void): void {
140	  ctrl = c; exit = onExit;
141	  window.addEventListener('keydown', (e) => {
142	    if (!active() || e.key === 'Escape') return;   // Esc do explore/index.ts xử lý (thoát chung); đang xem: không đọc phím
143	    if (e.ctrlKey || e.metaKey || e.altKey) return;   // phím tắt trình duyệt không điều khiển nhân vật, tránh kẹt phím
144	    if (isField(e.target)) return;                    // gõ trong ô nhập / chọn không điều khiển nhân vật
145	    exMulti.activity();   // phím điều khiển (kể cả tự lặp) tính là còn đó
146	    const k = e.key.toLowerCase();
147	    if (k === ' ') { e.preventDefault(); if (!e.repeat) jumpQueued = true; }
148	    else if (k.startsWith('arrow')) e.preventDefault();
149	    keys.add(k);
150	  });
151	  window.addEventListener('keyup', (e) => {
152	    keys.delete(e.key.toLowerCase());
153	    if (e.key === ' ' && active() && !isField(e.target)) e.preventDefault();   // Space không bấm nút đang focus
154	  });
155	  const drop = () => { keys.clear(); jumpQueued = false; };
156	  window.addEventListener('blur', drop);
157	  document.addEventListener('visibilitychange', () => { if (document.hidden) drop(); });
158	  window.addEventListener('focusin', (e) => { if (active() && isField(e.target)) drop(); });
159	  /* Kéo chuột trái trên canvas: xoay camera (cảm ứng ở Task 8) */
160	  let dragId = -1, lx = 0, ly = 0;
161	  canvas.addEventListener('pointerdown', (e) => {
162	    if (!active() || e.pointerType === 'touch' || e.button !== 0) return;
163	    dragId = e.pointerId; lx = e.clientX; ly = e.clientY;
164	    canvas.setPointerCapture(e.pointerId);
165	  });
166	  canvas.addEventListener('pointermove', (e) => {
167	    if (e.pointerId !== dragId) return;
168	    stCamDrag(camS, e.clientX - lx, e.clientY - ly, CONFIG.stroll.cam.mouse);
169	    exMulti.activity();   // xoay camera cũng tính là còn đó
170	    lx = e.clientX; ly = e.clientY;
171	  });
172	  const end = (e: PointerEvent) => { if (e.pointerId === dragId) dragId = -1; };
173	  canvas.addEventListener('pointerup', end);
174	  canvas.addEventListener('pointercancel', end);
175	  canvas.addEventListener('lostpointercapture', end);
176	}
177

1	/* ============================ Đi dạo: đầu vào từ bàn phím (thuần) ============================
2	   W/↑ tới, S/↓ lùi, A/← trái, D/→ phải theo hướng camera; chéo chuẩn hóa về độ dài 1; Shift chạy; Space nhảy.
3	   Nhảy ở đây chỉ phản ánh phím đang giữ: index.ts biến nó thành một lần nhảy mỗi lần bấm (stStep nhảy mỗi khung jump = true khi chạm đất).
4	   Không cấp phát (gọi mỗi khung). */
5	import type { StInput } from './motion';
6	
7	export function stInputFromKeys(keys: Set<string>, camYaw: number, out: StInput): StInput {
8	  let f = 0, r = 0;
9	  if (keys.has('w') || keys.has('arrowup')) f += 1;
10	  if (keys.has('s') || keys.has('arrowdown')) f -= 1;
11	  if (keys.has('d') || keys.has('arrowright')) r += 1;
12	  if (keys.has('a') || keys.has('arrowleft')) r -= 1;
13	  const len = Math.sqrt(f * f + r * r);
14	  if (len > 1) { f /= len; r /= len; }
15	  out.mz = f; out.mx = r; out.run = keys.has('shift'); out.jump = keys.has(' '); out.camYaw = camYaw;
16	  return out;
17	}
18

1	/* ============================ Đi dạo: camera sau lưng ============================
2	   Camera quay quanh tâm xoay ở độ cao `cam.height` trên chân nhân vật, lùi `dist` theo yaw / pitch người chơi chọn (không tự quay theo nhân vật),
3	   nhìn vào điểm `cam.look` trên chân. Tâm xoay trễ `lag` giây theo nhân vật cho chuyển động mềm.
4	   Tránh vật cản bằng bản đồ 2D (spec §3 mục 4): đoạn mặt bằng từ TÂM NHÂN VẬT (vị trí thật, luôn hợp lệ) tới chỗ camera muốn đứng cắt bởi stSegClear
5	   (tường cao vô hạn + mép vùng đi được), lùi thêm `gap`. Tường là cao vô hạn nên camera bị kéo lại gần thì nâng lên cho khoảng cách 3D tới tâm xoay
6	   vẫn ≥ minDist (= max(minDist, dist × phần đi được) của plan, tính theo 3D): camera không bao giờ ra ngoài đoạn đã kiểm, nên không chui vào nhà.
7	   Khoảng mặt bằng cho phép co lại ngay, nở ra theo `lag` (không giật khi vừa thoát góc tường).
8	   Cuối cùng kẹp độ cao: ≥ cao độ đứng tại chỗ camera + 0,3 m, ngoài vùng thì ≥ landY. Không cấp phát (D-018). */
9	import * as THREE from 'three';
10	import { CONFIG } from '../../config';
11	import { stSegClear, stGroundY, type StMap } from './map';
12	
13	export interface StCam { yaw: number; pitch: number }
14	
15	const ST_CAM_FLOOR = 0.3;   // m — camera cao hơn cao độ đứng tại chỗ nó ít nhất chừng này (plan Task 6)
16	const piv = { x: 0, y: 0, z: 0, ok: false };   // tâm xoay đã trễ
17	let reach = Infinity;                           // khoảng mặt bằng camera đang được phép lùi, m
18	
19	export function stCamPlace(camera: THREE.PerspectiveCamera, target: THREE.Vector3, s: { x: number; y: number; z: number }, c: StCam, map: StMap, dt: number, snap?: boolean): void {
20	  const K = CONFIG.stroll.cam;
21	  /* 1) tâm xoay trễ theo nhân vật */
22	  const hy = s.y + K.height;
23	  if (snap || !piv.ok) { piv.x = s.x; piv.y = hy; piv.z = s.z; piv.ok = true; }
24	  else if (dt > 0) { const k = 1 - Math.exp(-dt / K.lag); piv.x += (s.x - piv.x) * k; piv.y += (hy - piv.y) * k; piv.z += (s.z - piv.z) * k; }
25	  /* 2) chỗ camera muốn đứng: lùi dist theo yaw / pitch */
26	  const cp = Math.cos(c.pitch), sp = Math.sin(c.pitch), fx = Math.cos(c.yaw), fz = -Math.sin(c.yaw);
27	  const bx = piv.x - fx * K.dist * cp, bz = piv.z - fz * K.dist * cp;
28	  let cy = piv.y + K.dist * sp;
29	  /* 3) cắt theo bản đồ từ tâm nhân vật */
30	  let dx = bx - s.x, dz = bz - s.z;
31	  const L = Math.sqrt(dx * dx + dz * dz);
32	  if (L > 1e-6) { dx /= L; dz /= L; } else { dx = -fx; dz = -fz; }
33	  const t = L > 1e-6 ? stSegClear(map, s.x, s.z, bx, bz) : 1;
34	  let allow = t >= 1 ? L : L * t - K.gap;
35	  if (allow < 0) allow = 0;
36	  if (snap || allow < reach || !(dt > 0)) reach = allow;
37	  else reach += (allow - reach) * (1 - Math.exp(-dt / K.lag));
38	  const h = reach < L ? reach : L;
39	  const cx = s.x + dx * h, cz = s.z + dz * h;
40	  /* 4) khoảng cách 3D tới tâm xoay thật ≥ minDist: thiếu thì nâng camera (không lùi thêm vào tường) */
41	  const up = cy - hy;
42	  if (h * h + up * up < K.minDist * K.minDist) { const need = Math.sqrt(K.minDist * K.minDist - h * h); if (up < need) cy = hy + need; }
43	  /* 5) không thấp hơn mặt đứng tại chỗ camera / mặt đất */
44	  const g = stGroundY(map, cx, cz);
45	  const floor = g === g ? g + ST_CAM_FLOOR : CONFIG.landY;
46	  if (cy < floor) cy = floor;
47	  camera.position.set(cx, cy, cz);
48	  target.set(piv.x, piv.y - K.height + K.look, piv.z);
49	  camera.lookAt(target);
50	}
