/* Đi dạo: điều khiển cảm ứng (explore/stroll/touch.ts). #stHud là lớp phủ trong suốt, chỉ các điều khiển nhận chạm; direction:ltr để ar (RTL) vẫn giữ cần gạt bên trái tay.
   Bố cục B: cần gạt trái dưới; phải chỉ Nhảy và 📷; vuốt nửa phải để xoay camera. Cần gạt, Nhảy, vuốt chỉ hiện khi không có chuột (hover:none); 📷 hiện cả trên máy tính */
#stHud,#stPad,#stJump,#stLook,#stPhoto,#stFlash{display:none;}
body.stroll #stHud{display:block;position:fixed;inset:0;z-index:4;pointer-events:none;touch-action:none;user-select:none;-webkit-user-select:none;-webkit-touch-callout:none;}
body.ex-watching #stHud{display:none;}
#stHud button{position:fixed;display:flex;align-items:center;justify-content:center;pointer-events:auto;touch-action:none;margin:0;padding:0;color:var(--text);background:var(--panel);border:1px solid var(--panel-line);border-radius:50%;font:600 13px/1 var(--font-body);cursor:pointer;-webkit-tap-highlight-color:transparent;}
body.stroll #stPhoto{display:flex;right:calc(14px + env(safe-area-inset-right,0px));top:calc(100px + env(safe-area-inset-top,0px));width:48px;height:48px;font-size:22px;}   /* dưới nút Thoát (top 56 px) */
body.compact.stroll #stPhoto{top:calc(60px + env(safe-area-inset-top,0px));}   /* nút Thoát cao 40 px ở top 8 px */
#stFlash{position:fixed;inset:0;background:#fff;opacity:0;pointer-events:none;}   /* chớp khi chụp (Task 9 bật bằng lớp .on) */
body.stroll #stFlash{display:block;}
#stFlash.on{opacity:.85;}
@media (hover:none){
  body.stroll #stPad{display:block;position:fixed;pointer-events:auto;touch-action:none;left:calc(24px + env(safe-area-inset-left,0px));bottom:calc(24px + env(safe-area-inset-bottom,0px));width:var(--st-pad,120px);height:var(--st-pad,120px);box-sizing:border-box;border-radius:50%;background:rgba(10,18,22,.4);border:2px solid var(--panel-line);}
  #stKnob{position:absolute;left:50%;top:50%;width:46px;height:46px;margin:-23px 0 0 -23px;border-radius:50%;background:rgba(230,189,106,.55);border:1px solid var(--gold);pointer-events:none;}
  body.stroll #stJump{display:flex;right:calc(24px + env(safe-area-inset-right,0px));bottom:calc(150px + env(safe-area-inset-bottom,0px));width:72px;height:72px;}   /* trên danh sách người chơi (cao tối đa khoảng 140 px) */
  body.stroll #stLook{display:block;position:fixed;pointer-events:auto;touch-action:none;right:0;width:50%;top:calc(110px + env(safe-area-inset-top,0px));bottom:0;}   /* nửa phải, dưới nút Thoát và 📷; Nhảy nằm trên nó */
  body.stroll #exMpRoster:not([hidden]){inset-inline-end:auto;right:calc(14px + env(safe-area-inset-right,0px));}   /* ar: danh sách vẫn ở phải, không đè cần gạt bên trái */
}
body.compact #exHint{top:calc(64px + env(safe-area-inset-top,0px));}

